<script setup>
import { computed, onMounted, ref } from 'vue';
const batches=ref([]), selected=ref(null), file=ref(null), loading=ref(false), error=ref(''), center=ref(''), token=ref(''), result=ref(''), copied=ref(''), acknowledgeUnsupported=ref(false);
const scriptURL=`${window.location.origin}/scripts/send_nginx_config_script.sh`;
const curlCommand=`curl -fsSL '${scriptURL}' | base64 -d | bash`;
const wgetCommand=`wget -qO- '${scriptURL}' | base64 -d | bash`;
const api=async(path,options={})=>{const r=await fetch(path,options);if(!r.ok)throw new Error(await r.text());return r.json()};
async function refresh(){batches.value=await api('/api/batches');if(selected.value)selected.value=await api(`/api/batches/${selected.value.id}`)}
onMounted(()=>refresh().catch(e=>error.value=e.message));
async function upload(){if(!file.value)return;loading.value=true;error.value='';try{const data=new FormData();data.append('file',file.value);selected.value=await api('/api/batches',{method:'POST',body:data});acknowledgeUnsupported.value=false;await refresh()}catch(e){error.value=e.message}finally{loading.value=false}}
async function importBatch(){if(!selected.value||hasTLS.value)return;if(unsupported.value.length&&!acknowledgeUnsupported.value)return;loading.value=true;error.value='';result.value='';try{const value=await api(`/api/batches/${selected.value.id}/import`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({centerId:center.value,token:token.value,acknowledgeUnsupported:acknowledgeUnsupported.value})});selected.value=value.batch;result.value=value.message;await refresh()}catch(e){error.value=e.message}finally{loading.value=false}}
const unsupported=computed(()=>selected.value?.preview?.unsupported||[]);
const hasTLS=computed(()=>selected.value?.preview?.servers?.some(s=>s.tls)||false);
const canImport=computed(()=>!hasTLS.value&&(!unsupported.value.length||acknowledgeUnsupported.value));
function choose(e){file.value=e.target.files?.[0]||null}
function selectBatch(batch){selected.value=batch;acknowledgeUnsupported.value=false}
async function copyCommand(kind,command){try{await navigator.clipboard.writeText(command);copied.value=kind;setTimeout(()=>copied.value='',1800)}catch{error.value='复制失败，请手动选择并复制命令。'}}
</script>
<template><main><header><div><div class="eyebrow">ORP MIGRATION WORKSPACE</div><h1>NGINX 配置迁移</h1><p>上传 <code>nginx -T</code> 输出，查看转换结果，再导入 ORP 配置中心。</p></div><div class="pill">原文留档 · 可追溯</div></header>
<section class="collector card"><div class="collector-heading"><div><span class="tag">HOST COLLECTOR</span><h2>在 NGINX 主机上快速采集</h2><p>端点返回 Base64 编码脚本；复制命令会先解码，再交给 Bash 执行。</p></div><a class="script-link" :href="scriptURL">查看 Base64 ↗</a></div><div class="command-row"><span class="command-label">curl</span><code>{{curlCommand}}</code><button class="copy-button" @click="copyCommand('curl',curlCommand)">{{copied==='curl'?'已复制':'复制命令'}}</button></div><div class="command-row"><span class="command-label">wget</span><code>{{wgetCommand}}</code><button class="copy-button" @click="copyCommand('wget',wgetCommand)">{{copied==='wget'?'已复制':'复制命令'}}</button></div><p class="collector-footnote">执行需要目标主机能读取 NGINX 进程信息，并具备所需的 Docker 权限。脚本默认向其配置的上传 API 地址发送采集结果。</p></section>
<section class="upload card"><div><h2>新建迁移批次</h2><p>支持带有配置文件标记的 nginx -T 文本，最大 32 MB。</p></div><label class="file"><input type="file" accept=".txt,.conf,text/plain" @change="choose"><span>{{file?.name||'选择 nginx -T 输出文件'}}</span></label><button class="primary" :disabled="!file||loading" @click="upload">{{loading?'正在解析…':'上传并预览'}}</button></section>
<div v-if="error" class="notice error">{{error}}</div><div v-if="result" class="notice success">{{result}}</div>
<div class="layout"><aside class="card"><div class="section-title"><h2>迁移批次</h2><button class="quiet" @click="refresh">刷新</button></div><button v-for="b in batches" :key="b.id" class="batch" :class="{active:selected?.id===b.id}" @click="selectBatch(b)"><b>{{b.name}}</b><small>{{new Date(b.uploadedAt).toLocaleString()}}</small><small>{{b.preview?.servers?.length||0}} 个 Server · {{b.preview?.unsupported?.length||0}} 项待处理</small></button><p v-if="!batches.length" class="empty">上传文件后，迁移批次会显示在这里。</p></aside>
<section v-if="selected" class="card detail"><div class="section-title"><div><h2>{{selected.name}}</h2><p>SHA-256：<code>{{selected.sha256}}</code></p></div><span class="pill">{{selected.importedAt?'已导入':'待预览'}}</span></div><div class="stats"><div><strong>{{selected.preview?.upstreams?.length||0}}</strong><span>HTTP 上游</span></div><div><strong>{{selected.preview?.servers?.length||0}}</strong><span>HTTP Server</span></div><div class="warn-stat"><strong>{{unsupported.length}}</strong><span>待人工处理</span></div></div>
<h3>转换预览</h3><article v-for="u in selected.preview?.upstreams" :key="u.name" class="resource"><div><span class="tag">UPSTREAM</span><b>{{u.name}}</b></div><p>{{u.targets.map(t=>`${t.host}:${t.port}${t.backup?' (backup)':''}`).join(' · ')||'没有可转换的节点'}}</p></article><article v-for="(s,i) in selected.preview?.servers" :key="i" class="resource"><div><span class="tag blue">SERVER</span><b>{{s.names.join(', ')||'缺少 server_name'}}</b><span class="muted">:{{s.listenPort}}{{s.tls?' · TLS 监听':''}}</span></div><p>{{s.locations.map(l=>`${l.modifier}${l.path}${l.proxyPass?' → '+l.proxyPass:''}`).join('　')||'无 Location'}}</p></article>
<div class="section-title issue-heading"><h3>未支持或需确认的指令</h3><span>{{unsupported.length}} 项</span></div><div v-if="unsupported.length" class="issues"><div v-for="(x,i) in unsupported" :key="i" class="issue"><div><b>{{x.directive||'配置解析'}}</b><small>{{x.file}} · 第 {{x.line}} 行 · {{x.context}}</small></div><p>{{x.reason}}</p></div></div><p v-else class="empty">没有检测到待处理的指令。</p>
<div class="import-box" v-if="!selected.importedAt"><h3>导入到 ORP</h3><p>需有权访问该配置中心的 Bearer Token。导入只创建配置资源，不会自动校验、发布或 reload 网关。</p><div v-if="unsupported.length||hasTLS" class="migration-warning"><b>迁移风险，请检查后再继续</b><ul><li v-if="hasTLS">检测到 TLS 监听。当前无法按原语义导入，请先手动转换 TLS 配置；此批次暂不可导入。</li><li v-if="unsupported.length">有 {{unsupported.length}} 项指令未支持或需确认，导入结果可能与原配置不同。</li></ul></div><label v-if="unsupported.length" class="acknowledge"><input v-model="acknowledgeUnsupported" type="checkbox">我已阅读未支持指令清单，并接受导入结果可能不完整</label><div class="fields"><input v-model="center" placeholder="ORP 配置中心 UUID"><input v-model="token" type="password" placeholder="Bearer Token"></div><button class="primary" :disabled="loading||!center||!token||!canImport" @click="importBatch">{{loading?'正在导入…':'确认导入 ORP'}}</button><p v-if="unsupported.length&&!acknowledgeUnsupported" class="confirm-hint">勾选风险确认后才能继续导入。</p></div><p v-else class="empty">已导入中心：{{selected.importCenter}} · {{new Date(selected.importedAt).toLocaleString()}}</p></section><section v-else class="card placeholder"><div class="mark">↗</div><h2>选择一个迁移批次</h2><p>解析预览、转换结果和待处理指令将显示在这里。</p></section></div></main></template>
